// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The target address 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C has no receive/fallback
        // so a call with value will revert in the reference contract.
        // The mutant removes the revert check, so the call succeeds and transfers balance to owner.
        address owner = c.owner();
        vm.deal(owner, 100 ether);

        // Give some balance to the contract first (e.g. via fallback)
        vm.prank(address(0xdead));
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "initial funding failed");

        uint256 ownerBalanceBefore = owner.balance;

        // non-owner calls go() with 1 wei
        address attacker = address(0xbeef);
        vm.deal(attacker, 1 wei);
        vm.prank(attacker);
        (bool ok, ) = address(c).call{value: 1 wei}(abi.encodeWithSignature("go()"));

        uint256 ownerBalanceAfter = owner.balance;

        // In reference: go() reverts (target call fails) -> owner receives nothing, balance unchanged
        // In mutant: go() succeeds -> owner receives 1 ether + 1 wei, balance increases
        // This assertion should hold for reference (revert) and fail for mutant (transfer happened)
        assertTrue(ok == false, "Reference contract reverts but mutant succeeds");
    }
}

