pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = c.owner();
        address nonOwner = address(0x1234);

        // Fund the contract with some balance first so the transfer matters
        vm.deal(address(c), 1 ether);

        // nonOwner calls go() with 0 value
        vm.deal(nonOwner, 0);
        vm.prank(nonOwner);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("go()"));

        // Reference: reverts, so success == false, owner balance unchanged
        // Bug: succeeds, so success == true, owner gets contract balance
        assertTrue(!success, "Should revert when target call fails");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0x1);
    address nonOwner = address(0x2);

    function setUp() public { 
        vm.prank(owner);
        c = new C(); 
    }

    function testRegression_property() public {
        // Fund the contract via owner (who is already owner, but go() will also send balance to owner)
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        c.go{value: 1 ether}();
        // Now contract has 0 balance, owner has 1 ether (from the transfer)

        // Non-owner sends 1 wei — target call fails in reference, but succeeds in mutant
        vm.deal(nonOwner, 1 wei);
        vm.prank(nonOwner);
        bool ok;
        try c.go{value: 1 wei}() {
            ok = true;
        } catch {
            ok = false;
        }

        // In reference: revert -> ok = false; in mutant: success -> ok = true
        // Assert that the call reverts (reference behavior)
        assertTrue(!ok, "Expected revert on non-owner call with 1 wei");
    }
}

