// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        address nonOwner = address(0x1234);

        // Owner sends 1 ether to the contract via go() to set up balance
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        c.go{value: 1 ether}();

        // Now contract has 1 ether, owner has 0 (because transfer sent it back to owner, but let's reset for clarity)
        // Actually after owner's call, the contract balance becomes 0 and owner gets 1 ether back. We need contract to have balance.
        // Alternative: directly send ether to contract using a helper call.
        // Simpler: Use vm.deal to give contract 1 ether directly.
        vm.deal(address(c), 1 ether);

        // Record owner balance before non-owner call
        uint256 ownerBefore = owner.balance;

        // Non-owner calls go() with 1 wei
        vm.deal(nonOwner, 1 wei);
        vm.prank(nonOwner);
        (bool success, ) = address(c).call{value: 1 wei}(abi.encodeWithSignature("go()"));

        uint256 ownerAfter = owner.balance;

        // Reference: revert so owner balance unchanged; Bug: success, owner gets 1 ether transferred
        assertTrue(ownerAfter == ownerBefore + 1 ether, "owner balance should increase by 1 ether in bug");
    }
}
